CREATE TABLE schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE passkeys(id text PRIMARY KEY CHECK(length(id)<2048), user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, public_key bytea NOT NULL, counter bigint NOT NULL DEFAULT 0, transports jsonb NOT NULL DEFAULT '[]', name text NOT NULL DEFAULT 'Passkey' CHECK(length(name)<=64), backup_eligible boolean NOT NULL, backed_up boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE devices(id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, name text NOT NULL CHECK(length(name)<=64), public_key jsonb, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, device_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), last_seen timestamptz NOT NULL DEFAULT now(), verified_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE challenges(token_hash text PRIMARY KEY, kind text NOT NULL CHECK(kind IN('register','login','add','reauth')), challenge text NOT NULL, user_id uuid, expires_at timestamptz NOT NULL);
CREATE TABLE rate_limits(bucket text PRIMARY KEY, attempts integer NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE vaults(id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, key_id uuid NOT NULL, shared boolean NOT NULL DEFAULT false, epoch integer NOT NULL DEFAULT 1 CHECK(epoch>0), revision bigint NOT NULL DEFAULT 0 CHECK(revision>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE memberships(vault_id uuid NOT NULL REFERENCES vaults ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,role text NOT NULL CHECK(role IN('owner','admin','member','viewer')),PRIMARY KEY(vault_id,user_id));
CREATE TABLE sync_operations(operation_id uuid PRIMARY KEY,vault_id uuid NOT NULL REFERENCES vaults ON DELETE CASCADE,record_id text NOT NULL CHECK(length(record_id)<=80),device_id uuid REFERENCES devices ON DELETE SET NULL,base_revision bigint NOT NULL,revision bigint NOT NULL,envelope jsonb,tombstone boolean NOT NULL,conflict boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),CHECK(tombstone=(envelope IS NULL)),UNIQUE(vault_id,revision));
CREATE INDEX sync_revision ON sync_operations(vault_id,revision);
CREATE TABLE record_heads(vault_id uuid NOT NULL REFERENCES vaults ON DELETE CASCADE,record_id text NOT NULL,revision bigint NOT NULL,PRIMARY KEY(vault_id,record_id));
CREATE TABLE key_envelopes(vault_id uuid NOT NULL REFERENCES vaults ON DELETE CASCADE,recipient_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE,sender_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE,epoch integer NOT NULL,context jsonb NOT NULL,envelope jsonb NOT NULL,PRIMARY KEY(vault_id,recipient_id,epoch));
CREATE TABLE pairings(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,recipient_id uuid NOT NULL REFERENCES devices ON DELETE CASCADE,vault_id uuid NOT NULL REFERENCES vaults ON DELETE CASCADE,public_key jsonb NOT NULL,expires_at timestamptz NOT NULL,approved_at timestamptz,context jsonb,envelope jsonb);
CREATE TABLE security_events(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,kind text NOT NULL CHECK(length(kind)<=64),device_id uuid,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX events_user ON security_events(user_id,created_at DESC);
CREATE SCHEMA verifier;
CREATE TABLE verifier.applications(id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,name text NOT NULL CHECK(length(name)<=64));
CREATE TABLE verifier.api_keys(id uuid PRIMARY KEY,application_id uuid NOT NULL REFERENCES verifier.applications ON DELETE CASCADE,verifier text NOT NULL UNIQUE,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,last_used timestamptz);
CREATE TABLE verifier.credentials(id uuid PRIMARY KEY,application_id uuid NOT NULL REFERENCES verifier.applications ON DELETE CASCADE,subject_hash text NOT NULL,type text NOT NULL CHECK(type IN('totp','hotp')),algorithm text NOT NULL CHECK(algorithm IN('SHA-1','SHA-256','SHA-512')),digits integer NOT NULL CHECK(digits IN(6,8)),period integer NOT NULL CHECK(period BETWEEN 5 AND 300),counter numeric(20,0) NOT NULL DEFAULT 0,last_step bigint NOT NULL DEFAULT -1,envelope jsonb NOT NULL,active boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,subject_hash));
CREATE TABLE verifier.recovery_codes(credential_id uuid NOT NULL REFERENCES verifier.credentials ON DELETE CASCADE,verifier text NOT NULL,consumed_at timestamptz,PRIMARY KEY(credential_id,verifier));
INSERT INTO schema_migrations(version) VALUES(1);
